    Effect.flatMap((reply) => checkThemesReply(reply, comments)),
    Effect.map((themes): ThemesJobDecision => ({ _tag: "Store", themes })),
    Effect.catchTags({
      AiNotConfigured: (): Effect.Effect<ThemesJobDecision> => Effect.succeed({ _tag: "GiveUp" }),
