      questionVersionId: QB,
      position: 2,
      text: "How manageable is the workload?",
      type: ratingType,
      dimension: "workload",
      contributors: 2,
      meetsMinimumGroupSize: false,
      score: null,
      distribution: null,
      change: null,
      typicalChange: null,
      trend: [],
    },
  ],
  dimensions: [
    {
      dimension: "clarity",
      score: 3.4,
      usableQuestionCount: 1,
      totalQuestionCount: 1,
      contributors: 6,
      meetsMinimumGroupSize: true,
      change: {
        change: -0.8,
        previousRoundDate: "2026-10-26",
        previousRoundId: RoundId.make("round-prev"),
        matchedQuestionCount: 1,
        currentQuestionCount: 1,
        annotation: null,
        highlight: highlight(true),
      },
      typicalChange: null,
      trend: [],
    },
    {
      dimension: "workload",
      score: null,
      usableQuestionCount: 0,
      totalQuestionCount: 1,
      contributors: null,
      meetsMinimumGroupSize: false,
      change: null,
      typicalChange: null,
      trend: [],
